import React, { useEffect } from 'react';

interface UsePopupWindowOptions {
  enabled?: boolean;
  phase?: string;
  disabled?: boolean; // NEW: Accept disabled state from parent
  onDisable?: () => void;
  onToggle?: (disabled: boolean) => void; // NEW: Callback to communicate state changes
}

export const usePopupWindow = (options: UsePopupWindowOptions = {}) => {
  const { enabled = true, phase = '', disabled = false, onDisable, onToggle } = options;
  const [isDisabled, setIsDisabled] = React.useState(disabled);
  const currentPopup = React.useRef<Window | null>(null);
  const monitoringTimeout = React.useRef<NodeJS.Timeout | null>(null);

  // NEW: Sync with parent disabled state
  React.useEffect(() => {
    setIsDisabled(disabled);
  }, [disabled]);

  // NEW: Trigger popup creation when disabled state changes to false
  React.useEffect(() => {
    if (!isDisabled && enabled && phase) {
      console.log('🔄 Popup re-enabled - triggering creation...');
      // Force a re-run of the main popup creation logic
      // This will be handled by the main useEffect below
    }
  }, [isDisabled, enabled, phase]);

  // Function to disable popup functionality
  const disablePopup = React.useCallback(() => {
    console.log('🚫 Disabling popup functionality...');
    setIsDisabled(true);
    if (currentPopup.current && !currentPopup.current.closed) {
      try {
        currentPopup.current.close();
        console.log('🔒 Closed current popup');
      } catch (error) {
        console.log('⚠️ Could not close popup:', error);
      }
    }
    // Clear the popup reference
    currentPopup.current = null;
    // Clear any monitoring timeout
    if (monitoringTimeout.current) {
      clearTimeout(monitoringTimeout.current);
      monitoringTimeout.current = null;
    }
    if (onDisable) {
      onDisable();
    }
    // NEW: Communicate state change to parent
    if (onToggle) {
      onToggle(true);
    }
  }, [onDisable, onToggle]);

  // NEW: Function to enable popup functionality
  const enablePopup = React.useCallback(() => {
    console.log('✅ Enabling popup functionality...');
    setIsDisabled(false);
    // NEW: Communicate state change to parent
    if (onToggle) {
      onToggle(false);
    }
  }, [onToggle]);

  // NEW: Function to toggle popup functionality
  const togglePopup = React.useCallback(() => {
    if (isDisabled) {
      enablePopup();
    } else {
      disablePopup();
    }
  }, [isDisabled, enablePopup, disablePopup]);

  // Expose disable function globally for simulation controls
  React.useEffect(() => {
    (window as any).disablePopup = disablePopup;
    (window as any).enablePopup = enablePopup; // NEW: Expose enable function
    (window as any).togglePopup = togglePopup; // NEW: Expose toggle function
    return () => {
      delete (window as any).disablePopup;
      delete (window as any).enablePopup; // NEW: Clean up enable function
      delete (window as any).togglePopup; // NEW: Clean up toggle function
    };
  }, [disablePopup, enablePopup, togglePopup]); // NEW: Re-create functions when they change

  // Listen for disable messages from popup windows
  React.useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      console.log('📨 Received message:', event.data);
      if (event.data && event.data.type === 'DISABLE_POPUP') {
        console.log('📨 Received disable message from popup - disabling popup functionality');
        disablePopup();
      }
      // NEW: Handle toggle messages
      if (event.data && event.data.type === 'TOGGLE_POPUP') {
        console.log('📨 Received toggle message from popup - toggling popup functionality');
        togglePopup();
      }
    };

    window.addEventListener('message', handleMessage);
    return () => {
      window.removeEventListener('message', handleMessage);
    };
  }, [disablePopup, togglePopup]); // NEW: Re-create listener when functions change

  useEffect(() => {
    console.log('🔍 Popup hook triggered - enabled:', enabled, 'phase:', phase, 'disabled:', isDisabled);
    
    if (!enabled || !phase || isDisabled) {
      console.log('❌ Popup hook disabled, no phase, or manually disabled');
      return;
    }

    // Check if this is already a popup window
    const isPopupWindow = () => {
      console.log('🔍 Checking if window is popup...');
      console.log('Window opener:', window.opener);
      console.log('Window name:', window.name);
      console.log('Window inner width:', window.innerWidth);
      console.log('Window inner height:', window.innerHeight);
      console.log('Screen width:', window.screen.width);
      console.log('Screen height:', window.screen.height);
      console.log('Window screenX:', window.screenX);
      console.log('Window screenY:', window.screenY);
      
      // Check if window was opened by window.open()
      if (window.opener && window.opener !== window) {
        console.log('✅ Detected: Window has opener (popup)');
        return true;
      }
      
      // Check if window has specific popup characteristics
      if (window.name && window.name.includes('scareware')) {
        console.log('✅ Detected: Window name contains scareware (popup)');
        return true;
      }
      
      // Check if window is significantly smaller than screen (more reliable popup detection)
      const widthRatio = window.innerWidth / window.screen.width;
      const heightRatio = window.innerHeight / window.screen.height;
      console.log('📏 Window size ratios - width:', widthRatio.toFixed(2), 'height:', heightRatio.toFixed(2));
      
      // Only consider it a popup if it's very small (less than 50% of screen)
      if (widthRatio < 0.5 || heightRatio < 0.5) {
        console.log('✅ Detected: Window significantly smaller than screen (popup)');
        return true;
      }
      
      // Check if window is positioned at 0,0 (fullscreen popup behavior)
      if (window.screenX === 0 && window.screenY === 0) {
        console.log('✅ Detected: Window at 0,0 position (popup)');
        return true;
      }
      
      console.log('❌ Not detected as popup window');
      return false;
    };

    // Only spawn popup if we're not already in one AND not disabled
    if (!isPopupWindow() && !isDisabled) {
      console.log('🚀 Attempting to create popup window...');
      
      // Real scareware technique: Open new window in fullscreen
      const openFullscreenPopup = () => {
        try {
          var params = [
            'height=' + window.screen.height,
            'width=' + window.screen.width,
            'fullscreen=yes' // only works in IE, but here for completeness
          ].join(',');
          
          console.log('📋 Popup params:', params);
          console.log('🎯 Opening popup to URL:', `/${phase}`);
          
          // Real scareware technique: Use window.open with fullscreen features
          const popup = window.open(
            `/${phase}`, // Navigate to the same phase
            `scareware_${phase}_${Date.now()}`, // Unique window name
            params
          );
          
          console.log('📱 Popup result:', popup);
          
          if (popup) {
            console.log('✅ Popup created successfully!');
            // Store reference to current popup for disable functionality
            currentPopup.current = popup;
            
            // Add disable function to popup window
            try {
              (popup as any).disablePopup = () => {
                console.log('🚫 Popup disable triggered - sending message to parent');
                // Send message to parent window to disable popup functionality
                window.postMessage({ type: 'DISABLE_POPUP' }, '*');
                // Close this popup
                popup.close();
              };
            } catch (error) {
              console.log('⚠️ Could not add disable function to popup:', error);
            }
            
            // Real scareware technique: Move to 0,0 and focus the popup
            popup.moveTo(0, 0);
            popup.focus();
            
            // Monitor the popup window for closure (only if popup was successfully created)
            const monitorPopup = () => {
              // Check if popup functionality has been disabled
              if (isDisabled) {
                console.log('🚫 Popup monitoring disabled');
                return;
              }
              
              try {
                // Check if popup is closed
                if (popup.closed) {
                  console.log('🚨 Popup was closed - spawning new one...');
                  // Real scareware technique: Spawn new popup when one is closed
                  monitoringTimeout.current = setTimeout(() => {
                    if (!isDisabled) {
                      openFullscreenPopup();
                    }
                  }, 1000); // 1 second delay before spawning new popup
                  return;
                }
                
                // Continue monitoring
                monitoringTimeout.current = setTimeout(monitorPopup, 500); // Check every 500ms
              } catch (error) {
                console.log('⚠️ Error monitoring popup:', error);
                // If we can't access popup, it might be closed - spawn new one
                monitoringTimeout.current = setTimeout(() => {
                  if (!isDisabled) {
                    openFullscreenPopup();
                  }
                }, 1000);
              }
            };
            
            // Start monitoring the popup (only if popup exists)
            setTimeout(monitorPopup, 1000); // Start monitoring after 1 second
          } else {
            console.log('❌ Popup was blocked - trying fallback...');
            // Popup was blocked - try alternative approach
            try {
              // Try to resize current window to fullscreen
              window.resizeTo(window.screen.width, window.screen.height);
              window.moveTo(0, 0);
              console.log('🔄 Fallback: Resized current window');
            } catch (error) {
              console.log('⚠️ Fallback failed:', error);
            }
          }
        } catch (error) {
          console.log('💥 Error creating popup:', error);
        }
      };

      // Small delay to ensure page is loaded
      const timer = setTimeout(openFullscreenPopup, 100);
      console.log('⏰ Set timer for popup creation (100ms delay)');
      
      return () => {
        console.log('🧹 Cleaning up popup timer');
        clearTimeout(timer);
      };
    } else {
      console.log('✅ Already in popup window - no action needed');
    }
  }, [enabled, phase, isDisabled]);

  // Cleanup effect to clear monitoring timeout when disabled
  React.useEffect(() => {
    return () => {
      if (monitoringTimeout.current) {
        clearTimeout(monitoringTimeout.current);
        monitoringTimeout.current = null;
      }
    };
  }, []);
};
